EVALUATION_SOURCE = "\ndef rank_metrics(ranks):\n    a=np.asarray(ranks,dtype=np.int64)\n    if not len(a):return {'num_queries':0,'MRR':None}\n    return dict(num_queries=len(a),MRR=float((1./a).mean()),**{f'Recall@{k}':float((a<=k).mean()) for k in [1,5,10,50]})\ndef zscore(a):return (a-a.mean(-1,keepdim=True))/a.std(-1,keepdim=True,correction=1).clamp_min(1e-6)\ndef evaluate_validation():\n    model.eval()\n    with torch.no_grad():\n        all_joint=torch.cat([model.joint(torch.arange(s,min(s+1024,N),device=DEVICE)) for s in range(0,N,1024)])\n        ranks={str(a):[] for a in CFG['alpha_grid']}\n        for start in range(0,len(val_q),32):\n            rows=val_q.iloc[start:start+32];size=len(rows)\n            image_rows=CLIP_CACHE['top_rows'][start:start+size]\n            clip=CLIP_CACHE['scores'][start:start+size].to(DEVICE)\n            graph=torch.zeros_like(clip)\n            indirect=torch.tensor(rows.prediction_direction.ne('direct').to_numpy(),device=DEVICE)\n            for i,row in enumerate(rows.itertuples(index=False)):\n                if row.prediction_direction=='direct':continue\n                ids=IMAGE_ENTITIES[image_rows[i]].to(DEVICE)\n                anchor=int(row.anchor_entity_index);rel=int(row.relation_index)\n                assert 0<=anchor<N and 0<=rel<R\n                candidate=all_joint[ids];anchor_z=all_joint[anchor].expand_as(candidate)\n                r=model.rel_embeddings(torch.full_like(ids,rel))\n                h,t=(anchor_z,candidate) if row.prediction_direction=='tail' else (candidate,anchor_z)\n                graph[i]=model.margin-model._calc(h,t,r,'normal')\n            assert torch.isfinite(graph).all()\n            positives=CLIP_CACHE['positive_mask'][start:start+size].to(DEVICE)\n            baseline=CLIP_CACHE['baseline_rank'][start:start+size].to(DEVICE)\n            cz,gz=zscore(clip),zscore(graph)\n            for alpha in CFG['alpha_grid']:\n                if alpha==1.:rr=baseline\n                else:\n                    fused=alpha*cz+(1-alpha)*gz\n                    best=fused.masked_fill(~positives,float('-inf')).max(1).values\n                    inside=1+(fused>best[:,None]).sum(1)\n                    rr=torch.where(indirect & positives.any(1),inside,baseline)\n                ranks[str(alpha)].extend(rr.cpu().tolist())\n    seen=val_q.target_entity_index.isin(train_entities).to_numpy()\n    groups={'combined':np.ones(len(val_q),bool),'direct':val_q.prediction_direction.eq('direct').to_numpy(),\n        'head':val_q.prediction_direction.eq('head').to_numpy(),'tail':val_q.prediction_direction.eq('tail').to_numpy(),\n        'indirect':val_q.prediction_direction.ne('direct').to_numpy(),'seen-only':seen,'cold-start':~seen}\n    for population,mask in [('full',np.ones(len(val_q),bool)),('seen-only',seen),('cold-start',~seen)]:\n        for direction in ['combined','direct','head','tail','indirect']:\n            groups[population+'/'+direction]=mask & groups[direction]\n    metrics={a:{g:rank_metrics(np.array(rr)[mask]) for g,mask in groups.items()} for a,rr in ranks.items()}\n    best=max(CFG['alpha_grid'],key=lambda a:metrics[str(a)]['combined']['MRR'])\n    return best,metrics\n"
exec(EVALUATION_SOURCE)
